private fun cookingClock(at:Long,zone:TimeZone)=Instant.fromEpochSeconds(at).toLocalDateTime(zone).let{"${it.date} ${it.time.toString().take(5)}"}
@Composable internal fun ColumnScope.MealsOverview(rows:List<VisibleRecord>,day:String,view:String,zone:TimeZone,selectDay:(String)->Unit,selectView:(String)->Unit,open:(String,Long)->Unit,create:(String)->Unit,header:@Composable ()->Unit,canCreate:Boolean=true){
