 val meals=rows.map{it.record}.filter{it.isMeal()}.flatMap{eventInstances(it,first,end,zone)}
 VisibleLazyColumn(Modifier.fillMaxSize(),verticalArrangement=Arrangement.spacedBy(12.dp),contentPadding=PaddingValues(bottom=24.dp)){
 item{header();Text("Meals",style=MaterialTheme.typography.headlineSmall);Text("Ready times anchor your preparation. Open a meal for its items, phases and reminders.")}
 item{Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(8.dp)){for(mode in listOf("Day","Week","Month"))FilterChip(view==mode,{selectView(mode)},{Text(mode)})};Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){SecondaryButton(onClick={selectDay((if(view=="Month")first.minus(1,DateTimeUnit.MONTH)else first.minus(if(view=="Week")7 else 1,DateTimeUnit.DAY)).toString())}){Text("Previous")};SecondaryButton(onClick={selectDay((if(view=="Month")end else first.plus(if(view=="Week")7 else 1,DateTimeUnit.DAY)).toString())}){Text("Next")}};if(canCreate)Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick={create("dinner")},shape=ControlShape){Text("Plan food")};SecondaryButton(onClick={create("prep")}){Text("Plan prep")}}}
 items((0 until first.daysUntil(end)).map{first.plus(it,DateTimeUnit.DAY)},key={it.toString()}){date->Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Text(friendlyDate(date),style=MaterialTheme.typography.titleMedium);val entries=meals.filter{r->if(r.flag("all_day"))r.data.text("start_date")<=date.toString()&&r.data.text("end_date")>date.toString()else Instant.fromEpochSeconds(r.data.number("starts_at")).toLocalDateTime(zone).date==date};if(entries.isEmpty())Text("Nothing planned",color=MaterialTheme.colorScheme.onSurfaceVariant);for(r in entries)OutlinedCard(onClick={open(r.id,r.data.number("starts_at"))},modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text(r.data.text("title"),style=MaterialTheme.typography.titleMedium);Text(if(r.flag("all_day"))"All day"else "Ready "+cookingClock(r.data.number("starts_at"),zone));val p=cookingPlan(r);val start=p?.let{runCatching{cookingSchedule(it,r.data.number("starts_at")).firstOrNull()?.start}.getOrNull()};if(p!=null)Text("${p.items.size} items"+(start?.let{" · Begin "+cookingClock(it,zone)}?:""))}}}}
 }
}
@Composable internal fun CookingMeal(model:Workspace,state:WorkspaceState,record:Record,occurrence:Long,device:DeviceActions,editSchedule:()->Unit,close:()->Unit){
 val zone=TimeZone.currentSystemDefault();val plan=cookingPlan(record)?:CookingPlan();var edit by rememberSaveable{mutableStateOf(false)};var clearHistory by remember{mutableStateOf(false)};var reset by remember{mutableStateOf<CookingTime?>(null)};var warning by remember{mutableStateOf<CookingTime?>(null)};var error by remember{mutableStateOf<String?>(null)}
