 val writable=mayEdit&&state.cache.compatibility?.features?.contains("meal-workflow-v1")==true
 val times=runCatching{cookingSchedule(plan,occurrence)}.getOrDefault(emptyList())
 fun change(t:CookingTime,status:String){model.launch{try{model.enqueue("event.meal_stage",record.id,obj("occurrence" to occurrence.j(),"stage_id" to t.stage.id.j(),"state" to status.j(),"at" to Clock.System.now().epochSeconds.j()),record.revision,state.cache.snapshot!!.basis);model.requestSync()}catch(e:Exception){error=e.message}}}
 EditorDialog(onDismissRequest=close,title={Text(record.data.text("title"))},text={ScrollableColumn(verticalArrangement=Arrangement.spacedBy(12.dp)){
 if(writable&&plan.progress.any{it.state=="done"&&it.occurrence<Clock.System.now().epochSeconds-86400})SecondaryButton(onClick={clearHistory=true}){Text("Clear completed history")}
 Text("Ready "+cookingClock(occurrence,zone));Text("Times shown in ${zone.id}",style=MaterialTheme.typography.bodySmall);error?.let{Text(it,color=MaterialTheme.colorScheme.error)}
 if(record.flag("all_day"))Text("Set a ready time to calculate preparation.")
 else {times.firstOrNull()?.let{Text("Get started "+cookingClock(it.start,zone),style=MaterialTheme.typography.titleMedium)};val finish=times.maxOfOrNull{it.end}?:occurrence;if(finish>occurrence)Text("Current progress puts the meal ${(finish-occurrence+59)/60} minutes behind ready time.",color=MaterialTheme.colorScheme.error)
 if(times.isEmpty())Text(if(writable)"Add your own item and phase names, durations and dependencies."else if(mayEdit)"Update the server to add preparation phases. Schedule editing remains available."else"No preparation phases added.")
 for(t in times){HorizontalDivider();Text(t.stage.name,style=MaterialTheme.typography.titleMedium);Text("${t.item.name} · ${t.progress?.state?:"planned"}");Text(if(t.progress?.state=="done")"Completed "+cookingClock(t.end,zone)else cookingClock(t.start,zone)+" → "+cookingClock(t.end,zone));if(t.stage.after.isNotEmpty())Text("After "+t.stage.after.mapNotNull{id->times.find{it.stage.id==id}?.stage?.name}.joinToString());if(t.item.notes.isNotBlank())Text(t.item.notes);if(t.stage.notes.isNotBlank())Text(t.stage.notes)
 if(writable)Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(8.dp)){if(t.progress?.state!="done"){SecondaryButton(onClick={if(t.stage.after.any{id->plan.progress.none{it.occurrence==occurrence&&it.stage_id==id&&it.state=="done"}})warning=t else change(t,"running")}){Text(if(t.progress==null)"Start now"else"Restart timer")};SecondaryButton(onClick={change(t,"done")}){Text("Done")}};if(t.progress!=null)SecondaryButton(onClick={reset=t}){Text("Reset")}}}
 }
 }},confirmButton={if(writable&&!record.flag("all_day"))Button(shape=ControlShape,onClick={edit=true}){Text("Edit preparation")}},dismissButton={Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){if(mayEdit)SecondaryButton(onClick=editSchedule){Text("Schedule")};SecondaryButton(onClick=close){Text("Close")}}})
 if(clearHistory)EditorDialog(onDismissRequest={clearHistory=false},title={Text("Clear older completed history?")},text={Text("Clear completed phases for meals served more than 24 hours ago. Current and future meals and running timers are kept.")},confirmButton={Button(onClick={model.enqueueAsync("event.meal_clear",record.id,obj(),record.revision,state.cache.snapshot!!.basis);clearHistory=false}){Text("Clear history")}},dismissButton={SecondaryButton(onClick={clearHistory=false}){Text("Keep history")}})
 if(reset!=null)EditorDialog(onDismissRequest={reset=null},title={Text("Reset this phase?")},text={Text("Its timer and completion will be cleared for this date.")},confirmButton={Button(onClick={reset?.let{change(it,"planned")};reset=null}){Text("Reset phase")}},dismissButton={SecondaryButton(onClick={reset=null}){Text("Keep phase")}})
 if(warning!=null)EditorDialog(onDismissRequest={warning=null},title={Text("Start before prerequisites are complete?")},text={Text("Check that the required work is ready before starting this phase.")},confirmButton={Button(onClick={warning?.let{change(it,"running")};warning=null}){Text("Start phase")}},dismissButton={SecondaryButton(onClick={warning=null}){Text("Cancel")}})
 if(edit)CookingEditor(model,state,record,device){edit=false}
}
