 }},confirmButton={Button(shape=ControlShape,onClick={try{cookingSchedule(plan,record.data.number("starts_at"));model.launch{try{model.saveDraft(record.id,revision,fields(),basis,"event.update");model.submitDraft(record.id);model.requestSync();close()}catch(e:Exception){error=e.message}}}catch(e:Exception){error=e.message}}){Text("Save preparation")}},dismissButton={SecondaryButton(onClick=close){Text("Close")}})
